import{_ as a,o as s,c as t,ag as i}from"./chunks/framework.wGDfT7ie.js";const u=JSON.parse('{"title":"Reputation system","description":"","frontmatter":{},"headers":[],"relativePath":"reputation-system.md","filePath":"reputation-system.md"}'),n={name:"reputation-system.md"};function o(r,e,d,l,p,c){return s(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="reputation-system" tabindex="-1">Reputation system <a class="header-anchor" href="#reputation-system" aria-label="Permalink to &quot;Reputation system&quot;">​</a></h1><p>The reputation system assigns each user a <strong>tier</strong> that determines proof requirements, rate limits, relayer access, and protocol fees. Tiers are stored and updated by the backend; the frontend displays them on the Profile and uses them for gating.</p><h2 id="tiers" tabindex="-1">Tiers <a class="header-anchor" href="#tiers" aria-label="Permalink to &quot;Tiers&quot;">​</a></h2><ul><li><strong>Tier 0 (Strict)</strong> — Full ZKML proof per action (~2 min). Max 2 deposits/day, 1 withdrawal/day, 10 ETH position. No relayer. Fee 0.5%.</li><li><strong>Tier 1 (Standard)</strong> — Constraint-bounded (setup proof only). Max 10 deposits/day, 5 withdrawals/day, 50 ETH position. Relayer yes, 1 h delay. Fee 0.3%.</li><li><strong>Tier 2 (Express)</strong> — Optimistic + batched proofs. Max 255 deposits and withdrawals/day, unlimited position. Relayer yes, no delay. Fee 0.1%.</li></ul><p>These come from the backend <code>TIER_INFO</code>; the API returns <code>tier</code>, <code>tier_name</code>, and the same limits and flags.</p><h2 id="user-reputation-api" tabindex="-1">User reputation API <a class="header-anchor" href="#user-reputation-api" aria-label="Permalink to &quot;User reputation API&quot;">​</a></h2><p><strong>GET</strong> <code>/api/v1/zkdefi/reputation/user/{address}</code></p><p>Returns: <code>address</code>, <code>tier</code>, <code>tier_name</code>, <code>transaction_count</code>, <code>total_volume_eth</code>, <code>tenure_days</code>, <code>successful_txns</code>, <code>collateral_eth</code>, <code>upgrade_eligible</code>, <code>upgrade_requirements</code>.</p><p>The backend merges in-app history with chain-derived tenure and transaction counts. Profile Overview and Collateral use this via <code>useProfileReputation</code> for tier and stats.</p><h2 id="other-reputation-endpoints" tabindex="-1">Other reputation endpoints <a class="header-anchor" href="#other-reputation-endpoints" aria-label="Permalink to &quot;Other reputation endpoints&quot;">​</a></h2><ul><li><strong>GET</strong> <code>/api/v1/zkdefi/reputation/tiers</code> — List all tier definitions.</li><li><strong>POST</strong> stake-collateral and upgrade-tier — Collateral and tier upgrade.</li><li><strong>GET</strong> <code>/api/v1/zkdefi/reputation/staking/pools</code> — Staking pools list.</li><li><strong>GET</strong> <code>/api/v1/zkdefi/reputation/staking/positions/{address}</code> — User staking positions.</li><li><strong>POST</strong> <code>/api/v1/zkdefi/reputation/staking/stake</code> — Stake (body: address, pool_id, amount_wei).</li></ul><h2 id="data-flow" tabindex="-1">Data flow <a class="header-anchor" href="#data-flow" aria-label="Permalink to &quot;Data flow&quot;">​</a></h2><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart LR</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  TIER_INFO[Backend TIER_INFO]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  RepUser[GET reputation/user/address]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  Tiers[GET reputation/tiers]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  useProfileReputation[useProfileReputation]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  Profile[Profile page]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  TIER_INFO --&gt; RepUser</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  TIER_INFO --&gt; Tiers</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  RepUser --&gt; useProfileReputation</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  Tiers --&gt; Profile</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  useProfileReputation --&gt; Profile</span></span></code></pre></div><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><p>Tiers: Strict (0), Standard (1), Express (2). User reputation via <code>GET reputation/user/{address}</code>; used by Profile and Risk Passport. Staking: pools, positions, stake/claim/exit via reputation staking endpoints.</p><p>Next: <a href="/docs/risk-passport.html">Risk Passport</a> | <a href="/docs/profile-and-identity.html">Profile and identity</a></p>`,16)])])}const k=a(n,[["render",o]]);export{u as __pageData,k as default};
